import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { existsSync } from 'node:fs';
import { DocGraphClient } from '../DocGraphClient';
import type { ProcessRunner } from '../../search/RipgrepClient';
import type { Project } from '../../../domain/Project';

vi.mock('node:fs', async () => {
  const actual = await vi.importActual<typeof import('node:fs')>('node:fs');
  return {
    ...actual,
    existsSync: vi.fn(),
  };
});

describe('DocGraphClient', () => {
  const project: Project = { id: 'p1', name: 'Project 1', rootPath: '/test/project' };
  let mockRunner: ProcessRunner;
  let runFn: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    runFn = vi.fn();
    mockRunner = { run: runFn as unknown as ProcessRunner['run'] };
    vi.mocked(existsSync).mockReset();
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it('should return empty list if db file does not exist', async () => {
    vi.mocked(existsSync).mockReturnValue(false);
    const client = new DocGraphClient(mockRunner);
    const result = await client.findRelated(project, 'src/main.md');
    expect(result).toEqual([]);
    expect(runFn).not.toHaveBeenCalled();
  });

  it('should call command and parse json output on success', async () => {
    vi.mocked(existsSync).mockImplementation((path) => String(path).endsWith('graph.db'));
    runFn.mockResolvedValue({
      stdout: JSON.stringify({
        related: [
          { path: 'docs/test.md', reason: 'referenced', confidence: 0.9 }
        ]
      }),
      stderr: '',
      exitCode: 0
    });

    const client = new DocGraphClient(mockRunner);
    const result = await client.findRelated(project, 'src/main.md');
    expect(result).toEqual([
      { path: 'docs/test.md', reason: 'referenced', confidence: 0.9 }
    ]);
    expect(runFn).toHaveBeenCalledWith('docgraph', ['related', 'src/main.md', '--format', 'json'], '/test/project');
  });

  it('should fallback to empty list on command failure', async () => {
    vi.mocked(existsSync).mockImplementation((path) => String(path).endsWith('graph.db'));
    runFn.mockResolvedValue({ stdout: '', stderr: 'error', exitCode: 1 });
    const client = new DocGraphClient(mockRunner);
    const result = await client.findRelated(project, 'src/main.md');
    expect(result).toEqual([]);
  });

  it('should ignore malformed related entries', async () => {
    vi.mocked(existsSync).mockImplementation((path) => String(path).endsWith('graph.db'));
    runFn.mockResolvedValue({
      stdout: JSON.stringify({ related: [
        { path: 'docs/valid.md', reason: 'linked', confidence: 0.8 },
        { path: '../outside.md', reason: 'escape', confidence: 0.9 },
        { path: 'docs/no-score.md', reason: 'missing', confidence: Number.NaN },
        { path: 123, reason: 'wrong path', confidence: 0.5 },
      ] }),
      stderr: '',
      exitCode: 0,
    });

    const result = await new DocGraphClient(mockRunner).findRelated(project, 'src/main.md');

    expect(result).toEqual([{ path: 'docs/valid.md', reason: 'linked', confidence: 0.8 }]);
  });

  it('should use custom path if env var is set', async () => {
    vi.mocked(existsSync).mockImplementation((path) => String(path).endsWith('graph.db'));
    vi.stubEnv('CODEPREP_DOCGRAPH_PATH', '/custom/bin/docgraph');
    runFn.mockResolvedValue({ stdout: '{"related":[]}', stderr: '', exitCode: 0 });
    const client = new DocGraphClient(mockRunner);
    await client.findRelated(project, 'src/main.md');
    expect(runFn).toHaveBeenCalledWith('/custom/bin/docgraph', expect.any(Array), expect.any(String));
  });

  it('should use local exe if present', async () => {
    vi.mocked(existsSync).mockImplementation((path) => {
      const p = String(path);
      return p.endsWith('graph.db') || p.includes('docgraph.exe') || p.includes('docgraph');
    });
    runFn.mockResolvedValue({ stdout: '{"related":[]}', stderr: '', exitCode: 0 });
    const client = new DocGraphClient(mockRunner);
    await client.findRelated(project, 'src/main.md');
    expect(runFn.mock.calls[0][0]).toContain('docgraph');
  });
});

import { spawn } from 'child_process';
import type {
  AnalysisWarning,
  RipgrepPort,
  RipgrepResult,
} from '../../application/ports';
import type { Project } from '../../domain/Project';
import { parseRipgrepJson } from './RipgrepJsonParser';

export type ProcessOutput = Readonly<{
  stdout: string;
  stderr: string;
  exitCode: number;
}>;

export type ProcessRunner = Readonly<{
  run(command: string, args: readonly string[], cwd: string): Promise<ProcessOutput>;
}>;

export const nodeProcessRunner: ProcessRunner = { run: runProcess };

export class RipgrepClient implements RipgrepPort {
  public constructor(
    private readonly runner: ProcessRunner = nodeProcessRunner,
    private readonly excludes: readonly string[] = [],
  ) {}

  public async search(project: Project, query: string, contextLines: number): Promise<RipgrepResult> {
    try {
      const excludes = [...this.excludes, ...(project.excludePatterns ?? [])];
      const output = await this.runner.run('rg', rgArgs(query, contextLines, excludes), project.rootPath);
      return toRipgrepResult(project, output);
    } catch (error) {
      const warning = isMissingRgError(error) ? missingRgWarning(project) : rgFailureWarning(project);
      return { matches: [], warning };
    }
  }
}

const rgArgs = (
  query: string,
  contextLines: number,
  excludes: readonly string[],
): readonly string[] => [
  '--json',
  '--context',
  String(contextLines),
  '--hidden',
  ...excludes.flatMap(exclude => ['--glob', `!${exclude}`]),
  '--',
  query,
];

const toRipgrepResult = (project: Project, output: ProcessOutput): RipgrepResult => {
  if (output.exitCode <= 1) return { matches: parseRipgrepJson(output.stdout) };
  return { matches: [], warning: rgFailureWarning(project) };
};


const missingRgWarning = (project: Project): AnalysisWarning => ({
  kind: 'missingRg',
  projectId: project.id,
  message: 'Ripgrep is not available.',
});

const rgFailureWarning = (project: Project): AnalysisWarning => ({
  kind: 'rgFailure',
  projectId: project.id,
  message: 'Ripgrep search could not be completed.',
});

function runProcess(
  command: string,
  args: readonly string[],
  cwd: string,
): Promise<ProcessOutput> {
  return new Promise((resolve, reject) => {
    const child = spawn(command, [...args], { cwd, shell: false, stdio: ['ignore', 'pipe', 'pipe'] });
    const chunks = collectProcessChunks(child, resolve);
    child.stdout.on('data', chunks.stdout);
    child.stderr.on('data', chunks.stderr);
    child.on('error', reject);
  });
}

const collectProcessChunks = (
  child: ReturnType<typeof spawn>,
  resolve: (output: ProcessOutput) => void,
) => {
  const stdout: Buffer[] = [];
  const stderr: Buffer[] = [];
  child.on('close', code => {
    resolve({ stdout: join(stdout), stderr: join(stderr), exitCode: code ?? 1 });
  });
  return { stdout: pushChunk(stdout), stderr: pushChunk(stderr) };
};

const pushChunk = (chunks: Buffer[]) => (chunk: Buffer) => chunks.push(chunk);

const join = (chunks: readonly Buffer[]): string => Buffer.concat(chunks).toString('utf8');

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null;

const isMissingRgError = (error: unknown): boolean =>
  isRecord(error) && error.code === 'ENOENT';

import type { ProjectFilePort, RecommendationSourcePort } from '../../application/ports';
import { createRecommendation, type RecommendationRecord } from '../../domain/Recommendation';
import type { Project } from '../../domain/Project';

export class DirectoryProximityClient implements RecommendationSourcePort {
  public constructor(private readonly files: ProjectFilePort) {}

  public async recommend(project: Project, relativePath: string): Promise<readonly RecommendationRecord[]> {
    const normalized = normalize(relativePath);
    const directory = parentDirectory(normalized);
    const entries = await this.files.list(project);
    return entries
      .map(entry => normalize(entry.relativePath))
      .filter(path => path !== normalized && parentDirectory(path) === directory)
      .map(path => toRecommendation(project, path, normalized));
  }
}

const normalize = (value: string): string => value.replace(/\\/g, '/').replace(/^\.\//, '');

const parentDirectory = (value: string): string => {
  const separator = value.lastIndexOf('/');
  return separator < 0 ? '' : value.slice(0, separator);
};

const toRecommendation = (project: Project, relativePath: string, sourcePath: string): RecommendationRecord => {
  const recommendation = createRecommendation({
    projectId: project.id,
    relativePath,
    source: 'directoryProximity',
    score: 0.5,
    detail: `Same directory as ${sourcePath}`,
  });
  if (!recommendation) throw new Error('Invalid directory recommendation.');
  return recommendation;
};

